{
  "service": "gateway",
  "description": "gateway edge proxy",
  "listen": {
    "address": "127.0.0.1",
    "port": 8080
  },
  "tls": {
    "enabled": true,
    "verify_upstream": true,
    "min_version": "1.2"
  },
  "logging": {
    "level": "info",
    "format": "json",
    "sample_rate_pct": 100
  },
  "limits": {
    "max_body_kib": 512,
    "max_connections": 2048,
    "idle_timeout_s": 60
  },
  "features": {
    "compression": true,
    "http2": true,
    "request_ids": true
  },
  "upstreams": [
    {
      "name": "accounts",
      "host": "accounts.internal",
      "port": 8725,
      "weight": 8,
      "health_check": "/healthz"
    },
    {
      "name": "carts",
      "host": "carts.internal",
      "port": 7834,
      "weight": 1,
      "health_check": "/healthz"
    },
    {
      "name": "search",
      "host": "search.internal",
      "port": 9634,
      "weight": 1,
      "health_check": "/healthz"
    },
    {
      "name": "catalog",
      "host": "catalog.internal",
      "port": 9124,
      "weight": 4,
      "health_check": "/healthz"
    },
    {
      "name": "notifications",
      "host": "notifications.internal",
      "port": 9112,
      "weight": 10,
      "health_check": "/healthz"
    }
  ],
  "routes": [
    {
      "path": "/api/v1/accounts/events",
      "upstream": "accounts",
      "methods": [
        "GET"
      ],
      "timeout_ms": 1000,
      "retries": 2
    }
  ]
}

